// src/catalog/export/download.ts
import { EXPORT_HEADERS, mapExportRows } from "./rows";
import { encodeCsv } from "./csv";

type NamedProduct = { name: string };

export interface ExportDependencies {
  listProducts:
    () => readonly NamedProduct[] | Promise<readonly NamedProduct[]>;
  downloadBlob: (blob: Blob, filename: string) => void | Promise<void>;
}

export async function downloadCatalog(
  deps: ExportDependencies,
): Promise<void> {
  const products = await deps.listProducts();
  const csv = encodeCsv(EXPORT_HEADERS, mapExportRows(products));
  await deps.downloadBlob(
    new Blob([csv], { type: "text/csv;charset=utf-8" }),
    "catalog.csv",
  );
}
```

