function encodeCell(value: string): string {
  const needsPrefix = /^[\t\r\n]/u.test(value) || /^\s*[=+\-@]/u.test(value);
  const safeValue = needsPrefix ? "'" + value : value;
  return '"' + safeValue.replace(/"/g, '""') + '"';
}

export function encodeCsv(
  rows: readonly (readonly string[])[],
): string {
  return rows.map(row => row.map(encodeCell).join(",") + "\r\n").join("");
}

export function catalogCsv(products: readonly Product[]): string {
  return encodeCsv([CATALOG_HEADERS, ...mapCatalogRows(products)]);
}
```

