```js
function quoteCell(value) {
  const safe = /^[\t\r\n]|^\s*[=+\-@]/u.test(value)
    ? "'" + value
    : value;
  return '"' + safe.replaceAll('"', '""') + '"';
}

/**
 * @param {readonly string[]} headers
 * @param {readonly (readonly string[])[]} rows
 */
export function encodeCsv(headers, rows) {
  return [headers, ...rows]
    .map(row => row.map(quoteCell).join(','))
    .join('\r\n') + '\r\n';
}
```

