import { encodeCatalogCsv, mapCatalogRows } from "./catalogCsv";

type NamedProduct = { name: string };
type LoadProducts = () =>
  | readonly NamedProduct[]
  | Promise<readonly NamedProduct[]>;
type SaveBlob = (blob: Blob, filename: string) => void | Promise<void>;

export async function downloadCatalogCsv(
  loadProducts: LoadProducts,
  save: SaveBlob,
): Promise<void> {
  const products = await loadProducts();
  const csv = encodeCatalogCsv(mapCatalogRows(products));
  await save(
    new Blob([csv], { type: "text/csv;charset=utf-8" }),
    "catalog.csv",
  );
}
