export interface CatalogExportDependencies {
  listProducts: () =>
    | readonly { readonly name: string }[]
    | Promise<readonly { readonly name: string }[]>;
  downloadBlob: (blob: Blob, filename: string) => void;
}

export async function exportCatalogCsv(
  deps: CatalogExportDependencies,
): Promise<void> {
  const products = await deps.listProducts();
  const csv = encodeCatalogCsv(mapCatalogRows(products));

  deps.downloadBlob(
    new Blob([csv], { type: "text/csv;charset=utf-8" }),
    "catalog.csv",
  );
}
